def gen(rng):
    def rand(n, p):
        return ''.join('#' if rng.random() < p else rng.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(n))
    tests = ['a', '#', '##', '###', 'abc', 'ab#cdef##gh', 'ab##cde#fghij', '#a', 'a#', '#a#', 'a#a#a', '#a#b#c#d', 'abcdefg#', '#abcdefg',
             'a##b', 'a#b#c', 'aaaa#bbbb#cccc#dddd']
    for n in (2, 3, 5, 8, 12, 20, 30):
        for p in (0.1, 0.3, 0.6):
            tests.append(rand(n, p))
    for n in range(4, 30, 5):
        tests.append(rand(n, 0.2))
    n = 100000
    tests.append(rand(n, 0.05))
    tests.append(rand(n, 0.3))
    tests.append('#' * n)
    tests.append('a' * n)
    tests.append('a' * 50000 + '#' + 'b' * 49999)
    tests.append('#' + rand(n - 2, 0.0001) + '#')
    return tests
